import{n as e}from"./rolldown-runtime-2d059c5e81f4.js";import{t}from"./define-messages-8228c88ae861.js";var n;function r(){return(r=e((()=>{n=t({continueToPayPal:{id:`checkout.business.paypal.button.continue`,defaultMessage:`Continue to PayPal`,description:`Primary button in ChatGPT Business checkout when the next step opens PayPal to authorize a new payment method. This step does not itself confirm a completed purchase. PayPal is a brand name. Short button label with no placeholders.`},homeLinkLabel:{id:`checkout.homeLinkLabel`,defaultMessage:`ChatGPT home`,description:`Accessible name for the OpenAI logo link in the header of the full-page ChatGPT checkout. Activating the link leaves checkout and opens the ChatGPT home page without submitting payment. Short navigation label for screen-reader users; no placeholders.`},planNotAvailable:{id:`checkout.planNotAvailable.error`,defaultMessage:`This plan is currently unavailable for purchase.`,description:`Notice in pricing or checkout when the selected subscription plan cannot currently be purchased. Applies to any plan. Neutral explanation; the user may choose another available plan. One short sentence, no placeholders.`},paymentProcessing:{id:`CheckoutVerifyRoute.processingPayment`,description:`Short reassuring loading label beside a spinner on the checkout verification screen while a customer's payment is being finalized. Keep this label brief and use sentence case.`,defaultMessage:`Processing payment`},paymentSuccess:{id:`CheckoutForm.bannerMessagePaymentSuccess`,defaultMessage:`Payment successfully processed`,description:`Text for banner message that appears when a payment is successfully processed`},planDetailsTitle:{id:`CheckoutForm.headingPlanDetails`,defaultMessage:`Plan details`,description:`Heading for the checkout section that lets users confirm or adjust plan-specific details before submitting payment information.`},contactInformationTitle:{id:`CheckoutForm.headingContactInformation`,defaultMessage:`Contact information`,description:`Heading for the section of the checkout where we collect contact information`},paymentMethodTitle:{id:`CheckoutForm.headingPaymentMethod`,defaultMessage:`Payment method`,description:`Section heading shown above the payment method input (Stripe PaymentElement). Users select a payment option like card or PayPal.`},expressCheckoutTitle:{id:`CheckoutForm.headingExpressCheckout`,defaultMessage:`Pay with`,description:`Heading shown directly above a row of express wallet buttons (Apple Pay, Google Pay, etc.). Stands alone before the list and is not a button. Keep it short, sentence case, and do not add a colon or punctuation. Meaning: 'Pay using one of these methods.'`},billingAddressTitle:{id:`CheckoutForm.headingBillingAddress`,defaultMessage:`Billing address`,description:`Section heading shown above the billing address input (Stripe AddressElement). Used for billing and tax collection.`},billingAddressRequiredError:{id:`CheckoutForm.inputLabelBillingAddressRequired`,defaultMessage:`Your billing address is required.`,description:`Validation error for the billing address input when the billing address is missing`},minimalBillingTaxError:{id:`CheckoutForm.minimalBillingTaxError`,defaultMessage:`We couldn't calculate tax. Try again.`,description:`Inline error below the payment fields in ChatGPT subscription checkout when tax calculation fails while the Payment Element collects billing country and postal code. The accompanying Try again button recalculates tax without submitting payment. Short sentence; no placeholders.`},minimalBillingTaxRetry:{id:`CheckoutForm.minimalBillingTaxRetry`,defaultMessage:`Try again`,description:`Short button label beside a tax-calculation error in ChatGPT subscription checkout when the Payment Element collects billing country and postal code. Clicking retries the tax quote for the current country and postal code; it does not submit payment or start the subscription. Sentence case; no punctuation or placeholders.`},unsupportedBillingCountry:{id:`chatgpt.checkout.paypal_promo.form.billing_address.unsupported_country.error.v2`,defaultMessage:`This offer is only available in Germany. <continueToCheckoutLink>Continue to checkout without this offer.</continueToCheckoutLink>`,description:`Inline validation error in the PayPal Germany ChatGPT Plus cashback checkout. It appears when the customer selects a billing address outside Germany. The tagged text is a link that opens the standard ChatGPT Plus checkout without the PayPal cashback offer. German reference: Dieses Angebot ist nur in Deutschland verfügbar. <continueToCheckoutLink>Ohne dieses Angebot mit dem Checkout fortfahren.</continueToCheckoutLink>`},paypalBillingCountryMismatch:{id:`chatgpt.checkout.paypal_promo.form.billing_address.country_mismatch.error`,defaultMessage:`Your billing country must match this checkout. <continueToCheckoutLink>Continue to checkout without this offer.</continueToCheckoutLink>`,description:`Inline error on the PayPal ChatGPT Plus checkout when the billing country differs from the country used to create the checkout and select its currency. The tagged link opens standard Plus checkout without the PayPal offer.`},buttonSubscribe:{id:`CheckoutForm.buttonSubscribe`,defaultMessage:`Subscribe`,description:`Text for button that submits the form creating a new subscription`},buttonSubscribeToPlan:{id:`CheckoutForm.buttonSubscribeToPlan`,defaultMessage:`Subscribe to {planName}`,description:`Primary submit button label on the final step of the ChatGPT personal subscription checkout form, shown as the subscribe_to_plan variant of the subscribe_button_text experiment. Clicking it submits payment and starts the selected paid subscription; it is not shown for free-trial or non-subscription checkout. Short single-line button label. Placeholder {planName} is the bare official product tier name, such as Go, Plus, Pro Lite, or Pro; do not translate, localize, or inflect it. Translators may add their locale's word for plan outside the placeholder when needed for natural grammar.`},buttonPurchase:{id:`CheckoutForm.buttonPurchase`,defaultMessage:`Purchase`,description:`Text for button that submits the Codex usage-based checkout form.`},buttonUpgradeToPlan:{id:`CheckoutForm.buttonUpgradeToPlan`,defaultMessage:`Upgrade to {planName}`,description:`Primary submit button label on the ChatGPT personal plan checkout form, shown as one subscribe_button_text experiment variant. Trigger: a logged-in user with a Free account is on the final checkout submit step for the selected paid ChatGPT personal subscription plan; this experiment parameter is not read on free-trial checkout. Intent: make the final action feel plan-upgrade oriented without explicitly saying pay or charge. Short single-line button label. Placeholder {planName} is the bare official product tier name, such as Go, Plus, Pro Lite, or Pro; do not translate, localize, or inflect it. Translators may add their locale's word for plan outside the placeholder when needed for natural grammar.`},buttonStartYourPlan:{id:`CheckoutForm.buttonStartYourPlan`,defaultMessage:`Start your plan`,description:`Primary submit button label on the ChatGPT personal plan checkout form, shown as one subscribe_button_text experiment variant. Trigger: a logged-in user with a Free account is on the final checkout submit step for the selected paid ChatGPT personal subscription plan; this experiment parameter is not read on free-trial checkout. Intent: communicate that the user's selected subscription plan starts now without explicitly saying pay, charge, or trial. Short single-line button label; no placeholders. The word plan means the selected paid subscription plan, not a project plan or onboarding plan.`},buttonActivatePlan:{id:`CheckoutForm.buttonActivatePlan`,defaultMessage:`Activate {planName}`,description:`Primary submit button label on the ChatGPT personal plan checkout form, shown as one subscribe_button_text experiment variant. Trigger: a logged-in user with a Free account is on the final checkout submit step for the selected paid ChatGPT personal subscription plan; this experiment parameter is not read on free-trial checkout. Intent: communicate that submitting starts the selected subscription plan without explicitly saying pay, charge, or trial. Short single-line button label. Placeholder {planName} is the bare official product tier name, such as Go, Plus, Pro Lite, or Pro; do not translate, localize, or inflect it. Translators may add their locale's word for plan outside the placeholder when needed for natural grammar. Activate means starting the subscription plan, not enabling something the user already owns.`},buttonActivateTrial:{id:`CheckoutForm.buttonActivateTrial`,defaultMessage:`Activate {trialDurationInDays}-day trial`,description:`Trial checkout page primary CTA button label for the timeline checkout flow (web) for the user to activate their trialDurationInDays free trial`},buttonStartFreeTrial:{id:`CheckoutForm.buttonStartFreeTrial`,defaultMessage:`Start free trial`,description:`Checkout page primary CTA button label in the trial checkout flow (web). Trigger: shown when a logged-in user eligible for a Plus/Business free trial reaches the checkout form and submits the purchase. Audience: end users upgrading their plan; intent is reassuring and encouraging by highlighting that the trial starts now with no immediate charge. Constraints: very short, single-line button label in sentence case; no punctuation; avoid implying payment occurs now. Placeholders: none. This dedicated trial label is evaluated independently because non-trial subscribe_button_text variants are not read on free-trial checkout.`},buttonPayOtherWay:{id:`CheckoutForm.buttonPayOtherWay`,defaultMessage:`Pay other way`,description:`Button label in the ChatGPT subscription checkout modal when express wallet payments such as Apple Pay or Google Pay are available. End users click it to reveal the standard payment form with card, billing address, and subscribe controls instead of using an express wallet. Short single-line sentence-case label; no placeholders or punctuation.`},reactivationMemberRefreshError:{id:`CheckoutForm.reactivationMemberRefreshError`,defaultMessage:`We couldn't verify workspace members. Try again.`,description:`Retryable error toast shown when a deactivated Business workspace owner clicks the final checkout button but the app cannot refresh the paid-member count before submitting. The owner remains on the checkout page and can retry. Short sentence with no placeholders.`},walletPaymentOptionalTitle:{id:`CheckoutForm.walletPayment.optionalTitle`,defaultMessage:`Payment method <optional>(optional)</optional>`,description:`Short section heading in ChatGPT subscription checkout when gift-card wallet funds cover today's purchase including tax. The subscriber may add a backup payment method but does not have to. The optional tag renders that qualifier in a muted color; keep the parentheses with the qualifier.`},walletPaymentBackupDescription:{id:`CheckoutForm.walletPayment.backupDescription`,defaultMessage:`Your wallet balance is used first. Prevent your subscription from ending when your balance runs out by adding a backup payment method.`,description:`Multiline helper text under the optional payment method heading in ChatGPT subscription checkout. The wallet holds redeemed gift-card funds and covers today's purchase. Explain reassuringly that an optional backup method can keep the subscription active once those funds run out; this is not the wallet for agentic shopping. No placeholders.`},walletPaymentAddPaymentMethod:{id:`CheckoutForm.walletPayment.addPaymentMethod`,defaultMessage:`Add payment method`,description:`Short button label in ChatGPT subscription checkout when gift-card wallet funds cover today's purchase. Expands the optional backup payment form for future subscription charges. Clicking does not itself save a method or consent to future unrelated purchases.`},walletPaymentSkip:{id:`CheckoutForm.walletPayment.skip`,defaultMessage:`Skip for now`,description:`Button below the expanded optional backup payment form in ChatGPT subscription checkout. Hides that form and lets the subscriber finish today's fully Wallet-funded purchase without saving a payment method. Does not cancel the purchase. Short label.`}})})))()}export{r as n,n as t};
